/* ---------------- Signature connector (infinity motif) ---------------- */

function Connector() {
  return (
    <div className="hidden md:flex items-center justify-center relative">
      <svg width="120" height="64" viewBox="0 0 120 64" className="seek-connector" fill="none">
        <defs>
          <linearGradient id="connGrad" x1="0" y1="0" x2="120" y2="0">
            <stop offset="0%" stopColor={C.teal} />
            <stop offset="100%" stopColor={C.green} />
          </linearGradient>
        </defs>
        <path d="M4 32 C 30 4, 90 4, 116 32 C 90 60, 30 60, 4 32 Z" stroke="url(#connGrad)" strokeWidth="3" strokeLinecap="round" />
      </svg>
    </div>
  );
}

/* ---------------- Homepage ---------------- */

function HomePage({ setPage }) {
  const go = (id) => { setPage(id); window.scrollTo(0, 0); };
  const [requests, setRequests] = useState([]);
  const [requestsLoading, setRequestsLoading] = useState(true);
  const [requestsError, setRequestsError] = useState("");

  useEffect(() => {
    let cancelled = false;
    (async () => {
      try {
        const rows = await listPublishedRequests();
        if (!cancelled) setRequests(rows.map(mapRequestRow));
      } catch (err) {
        if (!cancelled) setRequestsError(err.message);
      } finally {
        if (!cancelled) setRequestsLoading(false);
      }
    })();
    return () => { cancelled = true; };
  }, []);

  return (
    <>
      {/* HERO */}
      <section className="relative overflow-hidden" style={{ background: `linear-gradient(180deg, ${C.bg}, #ffffff)` }}>
        <div className="mx-auto max-w-6xl px-5 sm:px-8 pt-16 pb-20 sm:pt-24 sm:pb-28 text-center">
          <SectionLabel>Seek · A project of BSN Foundation</SectionLabel>
          <h1 className="font-display font-extrabold text-[#0D3B3B] text-4xl sm:text-6xl leading-[1.05] max-w-3xl mx-auto">
            Everyone deserves a little help.
          </h1>
          <p className="mt-5 font-body text-lg text-[#0D3B3B]/70 max-w-xl mx-auto">
            Seek connects people who need help with people who are willing to give it.
          </p>
          <div className="mt-9 flex flex-col sm:flex-row items-center justify-center gap-3">
            <Button variant="primary" onClick={() => go("seek-help")}>I need help <ArrowRight size={16} /></Button>
            <Button variant="secondary" onClick={() => go("give")}>I want to help</Button>
          </div>
          <button onClick={() => go("volunteer")} className="mt-5 font-body text-sm text-[#0D3B3B]/55 hover:text-[#1BAA9C] underline underline-offset-4">
            Become a volunteer
          </button>
        </div>
      </section>

      {/* TWO-SIDED ENTRY */}
      <section className="mx-auto max-w-6xl px-5 sm:px-8 -mt-6 sm:-mt-10 pb-20 relative z-10">
        <div className="grid md:grid-cols-[1fr_auto_1fr] items-center gap-6">
          <div className="rounded-3xl p-8 sm:p-10 text-white shadow-xl" style={{ background: `linear-gradient(135deg, ${C.deepTeal}, #135050)` }}>
            <Search size={26} className="mb-4 text-[#63C167]" />
            <h3 className="font-display font-bold text-2xl mb-2">I need help</h3>
            <p className="font-body text-white/70 mb-6">Tell us what you need and let the community help you find it.</p>
            <Button variant="light" onClick={() => go("seek-help")}>Ask for help <ArrowRight size={16} /></Button>
          </div>
          <Connector />
          <div className="rounded-3xl p-8 sm:p-10 bg-white border border-[#0D3B3B]/8 shadow-xl">
            <HandHeart size={26} className="mb-4 text-[#1BAA9C]" />
            <h3 className="font-display font-bold text-2xl mb-2 text-[#0D3B3B]">I want to help</h3>
            <p className="font-body text-[#0D3B3B]/60 mb-6">Find people and families who need something you can provide.</p>
            <Button variant="primary" onClick={() => go("give")}>Find someone to help <ArrowRight size={16} /></Button>
          </div>
        </div>
      </section>

      {/* HOW SEEK WORKS */}
      <section className="bg-white py-20">
        <div className="mx-auto max-w-6xl px-5 sm:px-8">
          <div className="text-center mb-14">
            <SectionLabel>How it works</SectionLabel>
            <h2 className="font-display font-bold text-3xl sm:text-4xl text-[#0D3B3B]">Three simple steps.</h2>
          </div>
          <div className="grid sm:grid-cols-3 gap-8">
            {[
              { n: "01", t: "SEEK", d: "Tell us what you need." },
              { n: "02", t: "CONNECT", d: "Find someone willing to help." },
              { n: "03", t: "HELP", d: "Make a real difference." },
            ].map((s) => (
              <div key={s.n} className="text-center">
                <span className="font-display font-extrabold text-5xl bg-clip-text text-transparent" style={{ backgroundImage: `linear-gradient(135deg, ${C.teal}, ${C.green})` }}>{s.n}</span>
                <h3 className="font-display font-bold text-xl text-[#0D3B3B] mt-3 tracking-wide">{s.t}</h3>
                <p className="font-body text-[#0D3B3B]/60 mt-1">{s.d}</p>
              </div>
            ))}
          </div>
        </div>
      </section>

      {/* EXPLORE NEEDS */}
      <section className="py-20" style={{ background: C.bg }}>
        <div className="mx-auto max-w-6xl px-5 sm:px-8">
          <div className="mb-10">
            <SectionLabel>Categories</SectionLabel>
            <h2 className="font-display font-bold text-3xl sm:text-4xl text-[#0D3B3B]">What are people seeking?</h2>
          </div>
          <div className="grid grid-cols-2 sm:grid-cols-3 lg:grid-cols-4 gap-4">
            {CATEGORIES.map((c) => (
              <CategoryCard key={c.id} cat={c} onClick={() => go("seek-help")} />
            ))}
          </div>
        </div>
      </section>

      {/* PEOPLE WHO NEED HELP */}
      <section className="bg-white py-20">
        <div className="mx-auto max-w-6xl px-5 sm:px-8">
          <div className="flex items-end justify-between mb-10 flex-wrap gap-4">
            <div>
              <SectionLabel>Open requests</SectionLabel>
              <h2 className="font-display font-bold text-3xl sm:text-4xl text-[#0D3B3B] max-w-lg">Someone out there needs what you can give.</h2>
            </div>
            <button onClick={() => go("give")} className="inline-flex items-center gap-1 font-display font-semibold text-[#0D3B3B] hover:text-[#1BAA9C]">
              View all requests <ArrowRight size={16} />
            </button>
          </div>
          {requestsLoading ? (
            <p className="font-body text-sm text-[#0D3B3B]/50">Loading open requests…</p>
          ) : requestsError ? (
            <p className="font-body text-sm text-red-600">{requestsError}</p>
          ) : requests.length === 0 ? (
            <p className="font-body text-sm text-[#0D3B3B]/50">There are no published requests yet — check back soon.</p>
          ) : (
            <div className="grid sm:grid-cols-2 lg:grid-cols-4 gap-5">
              {requests.map((r) => <RequestCard key={r.id} req={r} onHelp={() => go("give")} />)}
            </div>
          )}
        </div>
      </section>

      {/* IMPACT */}
      <section className="py-20" style={{ background: `linear-gradient(135deg, ${C.deepTeal}, #123f3f)` }}>
        <div className="mx-auto max-w-6xl px-5 sm:px-8 text-center">
          <SectionLabel>Impact · Demo figures</SectionLabel>
          <h2 className="font-display font-bold text-3xl sm:text-4xl text-white mb-12">What community help can look like.</h2>
          <div className="grid grid-cols-2 lg:grid-cols-4 gap-8">
            {IMPACT_STATS.map((s) => (
              <div key={s.label}>
                <p className="font-display font-extrabold text-3xl sm:text-4xl text-white">{s.value}</p>
                <p className="font-body text-sm text-white/55 mt-1">{s.label}</p>
              </div>
            ))}
          </div>
          <p className="mt-10 text-xs text-white/35 font-body">Demo figures shown until live data is connected.</p>
        </div>
      </section>

      {/* BSN FOUNDATION */}
      <section className="bg-white py-20">
        <div className="mx-auto max-w-6xl px-5 sm:px-8">
          <div className="rounded-3xl p-10 sm:p-14 border border-[#0D3B3B]/8 grid md:grid-cols-[auto_1fr_auto] items-center gap-8" style={{ background: C.bg }}>
            <Building2 size={40} className="text-[#1BAA9C]" />
            <div>
              <p className="font-body text-xs font-semibold uppercase tracking-widest text-[#1BAA9C] mb-2">Powered by BSN Foundation</p>
              <p className="font-display font-semibold text-xl text-[#0D3B3B]">Seek is the community assistance platform built and supported by BSN Foundation.</p>
            </div>
            <Button variant="secondary" onClick={() => go("about")}>Learn about BSN Foundation</Button>
          </div>
        </div>
      </section>
    </>
  );
}

